import professionsJson from "./professions.json";
import recipesJson from "./recipes.json";
import itemsJson from "./items.json";
import locationsJson from "./locations.json";

// Generated by `npm run data` from the WoW: Forever client tables. Do not edit the JSON by hand.

// The only professions the app covers, in tab order.
export type ProfessionKey = "alchemy" | "herbalism" | "cooking" | "fishing" | "first-aid";

// A recipe group: TradeSkillCategory id and name. Id 0 is "Other" (the ability has no category).
export interface Category {
  id: number;
  name: string;
}

// One of the five covered professions.
export interface Profession {
  key: ProfessionKey;
  name: string;
  // Alchemy and Herbalism are primary professions, the other three secondary.
  tier: "primary" | "secondary";
  // SkillLine id of the profession.
  skillLine: number;
  // Categories used by this profession's recipes, in game order.
  categories: Category[];
  // Item ids this profession lists as gatherables. Look them up in `items`.
  gatherables: number[];
}

export interface Reagent {
  item: number;
  count: number;
}

export interface Recipe {
  // Spell id. Unique per profession (a spell can be taught by two professions).
  id: number;
  name: string;
  profession: ProfessionKey;
  // Category id, see Profession.categories.
  category: number;
  // Skill needed to learn it, and the skill range where it turns from orange to grey.
  minSkill: number;
  trivialLow: number;
  trivialHigh: number;
  // "item" when a recipe item (pattern, plans, formula...) teaches it. "trainer" otherwise: a trainer teaches it or it
  // comes with the profession (the client tables don't list trainers, so this is what's left without an item).
  source: "item" | "trainer";
  // Item created and how many, when the recipe creates one (enchants don't).
  item?: number;
  count?: number;
  reagents: Reagent[];
}

export interface Item {
  name: string;
  // 0 poor, 1 common, 2 uncommon, 3 rare, 4 epic, 5 legendary.
  quality: number;
  // Icon basename: https://wow.zamimg.com/images/wow/icons/large/<icon>.jpg. Null when unknown.
  icon: string | null;
}

export const professions = professionsJson as unknown as Profession[];
export const recipes = recipesJson as unknown as Recipe[];
export const items = itemsJson as unknown as Record<string, Item>;

// Where a Herbalism gatherable's nodes spawn in Forever. Derived from QuestieDB, see `source`.
export interface Locations {
  // Credit line for the data source and what was kept from it.
  source: string;
  // Client build the zone names come from.
  build: string;
  // Item id to English zone names, the zone with most spawns first. Items without nodes have no entry.
  items: Record<string, string[]>;
}

export const locations = locationsJson as unknown as Locations;
